import java.util.*;
import java.lang.*;

class Solution {
    /**
    Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parseNestedParens("(()()) ((())) () ((())()())")
    [2, 3, 1, 3]
     */
    public List<Integer> parseNestedParens(String paren_string) {
	List<Integer> output = new ArrayList<>();

	if (paren_string == null || paren_string.length() == 0) {
	    return output;
	}

	int max_depth = 0;
	int current_depth = 0;
	int start = 0;

	for (int i = 0; i < paren_string.length(); i++) {
	    if (paren_string.charAt(i) == '(') {
		current_depth++;
	    } else {
		current_depth--;
	    }

	    if (current_depth > max_depth) {
		max_depth = current_depth;
	    }

	    if (paren_string.charAt(i) == ')' && current_depth == 1) {
		int length = i - start + 1;
		output.add(length);
		start = i + 1;
	    }
	}

	return output;
    }

    }
public class Main {
    public static void main(String[] args) {
        Solution s = new Solution();
        List<Boolean> correct = Arrays.asList(
                s.parseNestedParens("(()()) ((())) () ((())()())").equals(Arrays.asList(2, 3, 1, 3)),
                s.parseNestedParens("() (()) ((())) (((())))").equals(Arrays.asList(1, 2, 3, 4)),
                s.parseNestedParens("(()(())((())))").equals(Arrays.asList(4))
        );
        if (correct.contains(false)) {
            throw new AssertionError();
        }
    }
}

