class Solution {
    /**
    Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest(List.of())
    Optional.empty
    >>> longest(Arrays.asList("a", "b", "c"))
    Optional[a]
    >>> longest(Arrays.asList("a", "bb", "ccc"))
    Optional[ccc]
     */
    public Optional<String> longest(List<String> strings) {
	if (strings.isEmpty()) {
	    return Optional.empty();
	}
	Optional<String> first = Optional.of(strings.get(0));
	for (int i = 1; i < strings.size(); i++) {
	    String candidate = strings.get(i);
	    if (candidate.length() > first.get().length()) {
		first = Optional.of(candidate);
	    } else if (candidate.length() == first.get().length()) {
		first = first.or(() -> Optional.of(candidate));
	    }
	}
	return first;
    }

    }
