    true
    >>> isPalindrome("zbcd")
    false
     */
    public boolean isPalindrome(String text) {
	text = text.toLowerCase();
	int left = 0;
	int right = text.length()-1;

	while(left<right){
	    if(text.charAt(left)!=text.charAt(right)){
		return false;
	    }
	    left++;
	    right--;
	}
	return true;
    }

    /**
    Checks if given binary tree is a mirror of itself
    >>> mirror(BinaryTree(3, BinaryTree(4, null, BinaryTree(5)), BinaryTree(6, null, BinaryTree(7))))
    true
     */
    public boolean mirror(BinaryTree root) {
	if(root==null){
	    return true;
	}

	if(!root.left.equals(root.right)){
	    return false;
	}
	return mirror(root.left) && mirror(root.right);
    }

    /**
    Checks if given binary tree is a binary search tree
    >>> isBinarySearchTree(BinaryTree(3, BinaryTree(2, null, BinaryTree(4)), BinaryTree(1, null, BinaryTree(6, null, BinaryTree(7)))))
    true
     */
    public boolean isBinarySearchTree(BinaryTree root) {
	if(root==null){
	    return true;
	}

	return isBinarySearchTree(root.left, Integer.MIN_VALUE, root.val) && isBinarySearchTree(root.right, root.val, Integer.MAX_VALUE);
    }

    private boolean isBinarySearchTree(BinaryTree root, int min, int max) {
	if(root==null){
	    return true;
	}
	if(root.val<=min || root.val>=max){
	    return false;
	}
	return isBinarySearchTree(root.left, min, root.val) && isBinarySearchTree(root.right, root.val, max);
    }

