class Solution {
    /**
    Return 2^n modulo p (be aware of numerics).
    >>> modp(3, 5)
    3
    >>> modp(1101, 101)
    2
    >>> modp(0, 101)
    1
    >>> modp(3, 11)
    8
    >>> modp(100, 101)
    1
     */
    public int modp(int n, int p) {
	if (n == 0) return 1;
	if (n == 1) return (p + p%2) % p;
	int res = modp(n/2, p);
	res = (res*res) % p;
	if (n%2 == 1) res = (res*p) % p;
	return res;
    }

    /**
    Count the number of 1s in binary representation
    of an integer n.
    >>> count1s(5)
