    20
    >>> count1s(-1000000000)
    20
    >>> count1s(Integer.MAX_VALUE)
    31
    >>> count1s(Integer.MIN_VALUE)
    31
    */
    public int count1s(int n) {
	int count = 0;
	while (n!= 0) {
	    count++;
	    n &= n-1;
	}
	return count;
    }
}
