import java.util.*;
import java.lang.*;

class Solution {
    /**
    Write a function vowelsCount which takes a string representing
    a word as input and returns the number of vowels in the string.
    Vowels in this case are 'a', 'e', 'i', 'o', 'u'. Here, 'y' is also a
    vowel, but only when it is at the end of the given word.

    Example:
    >>> vowelsCount("abcde")
    2
    >>> vowelsCount("ACEDY")
    3
     */
    public int vowelsCount(String s) {
	if (s.length() == 0) return 0;
	return helper(s, 0);
    }

    public int helper(String s, int index) {
	if (index >= s.length()) return 0;
	int vowels = 0;
	if (s.charAt(index) == 'a' || s.charAt(index) == 'e' || s.charAt(index) == 'i' || s.charAt(index) == 'o' || s.charAt(index) == 'u') vowels++;
	if (index == s.length() - 1 || (s.charAt(index)!= 'y' && s.charAt(index + 1)!= 'y')) return vowels + helper(s, index + 1);
	return vowels + helper(s, index + 2);
    }

    }
public class Main {
    public static void main(String[] args) {
        Solution s = new Solution();
        List<Boolean> correct = Arrays.asList(
                s.vowelsCount("abcde") == 2,
                s.vowelsCount("Alone") == 3,
