        int half = sum / 2;
        List<Integer> firstHalf = q.subList(0, half);
        List<Integer> secondHalf = q.subList(half, q.size());
        Collections.reverse(secondHalf);

        return firstHalf.equals(secondHalf) && sum <= w;
