import java.util.*;
import java.lang.*;

class Solution {
    /**
    Given an array arr of integers, find the minimum number of elements that
    need to be changed to make the array palindromic. A palindromic array is an array that
    is read the same backwards and forwards. In one change, you can change one element to any other element.

    For example:
    smallestChange(Arrays.asList(1,2,3,5,4,7,9,6)) == 4
    smallestChange(Arrays.asList(1, 2, 3, 4, 3, 2, 2)) == 1
    smallestChange(Arrays.asList(1, 2, 3, 2, 1)) == 0
     */
    public int smallestChange(List<Integer> arr) {
	if (arr.isEmpty()) return 0;
	if (arr.size() == 1) return 0;
	int index1 = 0;
	int index2 = arr.size()-1;
	int changeCount = 0;
	while (index1 < index2){
	    if (arr.get(index1)!= arr.get(index2)){
		int temp = arr.get(index2);
		arr.set(index2, arr.get(index1));
		arr.set(index1, temp);
		changeCount++;
	    }
	    index1++;
	    index2--;
	}
	return changeCount;
    }

    }
