class Solution {
    /**
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
     */
    public int startsOneEnds(int n) {
	assert n >= 1;
	int count = 0;
	for (int i = 0; i < 10; ++i) {
	    count += endsOne(n, i);
	}
	for (int i = 1; i < n; ++i) {
	    count += endsOne(i, 10);
	}
	return count;
    }

    /**
    Let the number of end digits be k.
    For example, for n = 24, the number of end digits is 2.
    The number of combinations of length n with all possible end digits are 10^k.
    We can get the number of end digits for a number by counting the number
    of 1's in the binary representation of that number.
    For example, for n = 24, the binary representation is 111100.
    Thus, the number of end digits is 3.
    The number of end digits is also equal to the number of trailing 0s in
    n!
    */
    private int endsOne(int n, int endDigit) {
	assert n >= 0;
	int count = 0;
	for (int i = n; i > 0; i /= 10) {
	    count += i % 10 == endDigit? 1 : 0;
	}
	return count;
    }

    }
