class Solution {
    /**
    Given an array of non-negative integers, return a copy of the given array after sorting,
    you will sort the given array in ascending order if the sum( first index value, last index value) is odd,
    or sort it in descending order if the sum( first index value, last index value) is even.

    Note:
    * don't change the given array.

    Examples:
    * sortArray(Arrays.asList()) => []
    * sortArray(Arrays.asList(5)) => [5]
    * sortArray(Arrays.asList(2, 4, 3, 0, 1, 5)) => [0, 1, 2, 3, 4, 5]
    * sortArray(Arrays.asList(2, 4, 3, 0, 1, 5, 6)) => [6, 5, 4, 3, 2, 1, 0]
     */
    public List<Integer> sortArray(List<Integer> array) {
	boolean sortInEven = false;
	int sum = 0, first = 0, last = array.size() - 1;
	for (int i = 0; i < array.size() - 1; i++)
	    sum += array.get(i) + array.get(i + 1);
	sortInEven = (sum % 2) == 0;
	if (sortInEven) {
	    for (int i = 0; i < array.size() / 2; i++) {
		int temp = array.get(first);
		array.set(first, array.get(last));
		array.set(last, temp);
		first++;
		last--;
	    }
	} else {
	    for (int i = array.size() - 1; i > array.size() / 2; i--) {
		int temp = array.get(first);
		array.set(first, array.get(last));
		array.set(last, temp);
		first++;
		last--;
	    }
	}
	return array;
    }

    }
