import java.util.*;
import java.lang.*;

class Solution {
    /**
    Task
    We are given two strings s and c, you have to deleted all the characters in s that are equal to any character in c
    then check if the result string is palindrome.
    A string is called palindrome if it reads the same backward as forward.
    You should return a tuple containing the result string and true/false for the check.
    Example
    For s = "abcde", c = "ae", the result should be ("bcd",false)
    For s = "abcdef", c = "b"  the result should be ("acdef",false)
    For s = "abcdedcba", c = "ab", the result should be ("cdedc",true)
     */
    public List<Object> reverseDelete(String s, String c) {
//        1. Delete all characters from s that are in c
//        2. Check if the resulting string is a palindrom
//        Time complexity: O(N) where N is the number of characters in s
//        Space complexity: O(N) where N is the number of characters in s
//        
//        Alternative:
//        1. Create a Set to store characters from c
//        2. Iterate over s and if the current character is not in the Set, add it to the result string
//        3. Check if the result string is a palindrom
//        Time complexity: O(N) where N is the number of characters in s
//        Space complexity: O(N) where N is the number of characters in s
        List<Object> result = new ArrayList<>();
        Set<Character> set1 = new HashSet<>();
        for (char ch : c.toCharArray()) {
            set1.add(ch);
        }
        StringBuilder sb = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (!set1.contains(ch)) {
                sb.append(ch);
            }
        }
        String reverse = sb.reverse().toString();
        if (sb.toString().equals(reverse)) {
            result.add(reverse);
            result.add(true);
        } else {
            result.add(sb.toString());
            result.add(false);
        }

        return result;
    }
}

