class Solution {
    /**
    Given a string s and a natural number n, you have been tasked to implement
    a function that returns a list of all words from string s that contain exactly
    n consonants, in order these words appear in the string s.
    If the string s is empty then the function should return an empty list.
    Note: you may assume the input string contains only letters and spaces.
    Examples:
    selectWords("Mary had a little lamb", 4) ==> ["little"]
    selectWords("Mary had a little lamb", 3) ==> ["Mary", "lamb"]
    selectWords("simple white space", 2) ==> []
    selectWords("Hello world", 4) ==> ["world"]
    selectWords("Uncle sam", 3) ==> ["Uncle"]
     */
    public List<String> selectWords(String s, int n) {
//        1. Count number of consonants in the string
//        2. Get a list of all words in the string
//        3. Filter the list of words based on the condition
        List<String> list = new ArrayList<>();
        if (s.isEmpty()) return list;

        int count = 0;
        StringBuilder word = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLetter(c)) {
                if (count == n) {
                    list.add(word.toString());
                    word = new StringBuilder();
                    count = 0;
                }
                word.append(c);
                count += Character.isConsonant(c)? 1 : 0;
            }
        }

        if (word.length() > 0 && count == n) list.add(word.toString());

        return list;
    }
}

