    Examples:
    matchParens(Arrays.asList("()(", ")")) == "Yes"
    matchParens(Arrays.asList(")", ")")) == "No"
     */
    public String matchParens(List<String> lst) {
//        int left = 0, right = 0;
//        for (String s : lst) {
//            for (int i = 0; i < s.length(); i++) {
//                if (s.charAt(i) == '(') left++;
//                else if (s.charAt(i) == ')') right++;
//            }
//        }
//        return left == right? "Yes" : "No";
        Stack<Character> stack = new Stack<>();
        for (String s : lst) {
            for (char c : s.toCharArray()) {
                if (c == '(' || c == '{' || c == '[') stack.push(c);
                else {
                    if (stack.size() > 0) {
                        if (stack.pop() == '(' && c == ')') continue;
                        if (stack.pop() == '{' && c == '}') continue;
                        if (stack.pop() == '[' && c == ']') continue;
                    }
                    return "No";
                }
            }
        }
        return stack.size() == 0? "Yes" : "No";
    }

