class Solution {
    /**
    You are given a word. Your task is to find the closest vowel that stands between
    two consonants from the right side of the word (case sensitive).

    Vowels in the beginning and ending doesn't count. Return empty string if you didn't
    find any vowel met the above condition.

    You may assume that the given string contains English letter only.

    Example:
    getClosestVowel("yogurt") ==> "u"
    getClosestVowel("FULL") ==> "U"
    getClosestVowel("quick") ==> ""
    getClosestVowel("ab") ==> ""
     */
    public String getClosestVowel(String word) {
//        1. Find all the vowels in the word
//        2. Find the min distance between these two vowels
//        3. Return the vowel that has the min distance

        List<Integer> vowels = new ArrayList<>();
        for (int i = 0; i < word.length(); i++) {
            if (isVowel(word.charAt(i))) {
                vowels.add(i);
            }
        }

        if (vowels.size() == 0) {
            return "";
        }

        int minDistance = Integer.MAX_VALUE;
        int index = 0;
        for (int i = 0; i < vowels.size() - 1; i++) {
            int distance = Math.abs(vowels.get(i) - vowels.get(i + 1));
            if (distance < minDistance) {
                minDistance = distance;
                index = i + 1;
            }
        }

        return word.charAt(vowels.get(index)) + "";
    }

    private boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    }
