	List<Integer> tmp = new ArrayList<>(n);
	tmp.add(grid.get(0).get(0));
	res.add(grid.get(0).get(0));
	for (int i = 1; i < n; i++) {
	    tmp.add(grid.get(i).get(0) + tmp.get(tmp.size() - 1));
	    res.add(grid.get(i).get(0) + tmp.get(tmp.size() - 1));
