class Solution {
    /**
    Create a function which returns the largest index of an element which
    is not greater than or equal to the element immediately preceding it. If
    no such element exists then return -1. The given array will not contain
    duplicate values.

    Examples:
    canArrange(Arrays.asList(1,2,4,3,5)) = 3
    canArrange(Arrays.asList(1,2,3)) = -1
     */
    public int canArrange(List<Integer> arr) {
//        2 pointers solution
//        Time complexity = O(n)
//        Space complexity = O(1)
//        https://leetcode.com/submissions/detail/352827509/

        int n = arr.size();
        int max = arr.get(n - 1);
        int index = -1;
        for (int i = n - 2; i >= 0; i--) {
            if (arr.get(i) <= max) {
                index = Math.max(index, i);
                max = arr.get(i);
            }
        }
        return index;
    }

    // Time complexity = O(n^2)
    // Space complexity = O(1)
    // https://leetcode.com/submissions/detail/352813518/
    public int canArrange2(List<Integer> arr) {
        int n = arr.size();
        if (n == 1) return -1;
        int index = 0;
        for (int i = 0; i < n; i++) {
            int max = arr.get(n-1);
            for (int j = n-2; j > i; j--) {
                if (arr.get(j) > arr.get(i)) max = arr.get(j);
            }
            if (max <= arr.get(i)) index = Math.max(index, i);
        }
        return index;
    }

    }
