     */
    public int specialFilter(List<Integer> nums) {
	int count = 0;
	for (int i = 0; i < nums.size(); i++) {
	    if (firstAndLastOdd(nums.get(i)) && numInArray(nums.get(i), 10)) {
		count++;
	    }
	}
	return count;
    }

    private boolean firstAndLastOdd(int num) {
	if (num >= 0) {
	    return ((num % 2 == 1) && ((num / 10) % 2 == 1));
	} else {
	    return ((num % 2 == -1) && ((num / 10) % 2 == -1));
	}
    }

