    for StrongestExtension("my_class", ["AA", "Be", "CC"]) == "my_class.AA"
     */
    public String StrongestExtension(String class_name, List<String> extensions) {
	int max_strength = 0;
	String answer = "";
	for (String extension : extensions) {
	    int cap = 0;
	    int sm = 0;
	    for (Character c : extension.toCharArray()) {
